'use strict';

// One describe block per symptom in ISSUE.md (INC-5521). Each test reproduces
// the failure against the pre-fix service and passes with the fix.

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  OrderStateError,
  UnknownSkuError
} = require('../src');
const { ticks, GatedStore, assertCountersMatchOrders } = require('./helpers/stores');

const DROP = 'sneaker-limited';

async function stocked(stock, options = {}) {
  const store = options.store || new Store();
  const svc = new InventoryService({ ...options, store });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return { svc, store };
}

function outcomes(results) {
  const fulfilled = results.filter(result => result.status === 'fulfilled');
  const rejected = results.filter(result => result.status === 'rejected');
  return { fulfilled, rejected };
}

describe('INC-5521: 263 orders confirmed for a 250-unit drop', () => {
  test('concurrent reserves never hold more units than are in stock', async () => {
    const { svc } = await stocked({ [DROP]: 250 });

    const results = await Promise.allSettled(
      Array.from({ length: 300 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: DROP, qty: 1 }]))
    );

    const { fulfilled, rejected } = outcomes(results);
    assert.equal(fulfilled.length, 250);
    assert.equal(rejected.length, 50);
    for (const { reason } of rejected) {
      assert.ok(reason instanceof InsufficientStockError, `unexpected rejection: ${reason}`);
    }
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 250, reserved: 250, sold: 0 });
    assert.equal(await svc.available(DROP), 0);
  });

  test('40 concurrent workers running reserve then commit sell exactly the stock', async () => {
    const { svc } = await stocked({ [DROP]: 250 });
    const orderIds = Array.from({ length: 263 }, (_, i) => `order-${i}`);
    let confirmed = 0;

    async function worker(queue) {
      for (const orderId of queue) {
        try {
          await svc.reserve(orderId, [{ sku: DROP, qty: 1 }]);
        } catch (err) {
          if (err instanceof InsufficientStockError) {
            continue;
          }
          throw err;
        }
        await svc.commit(orderId);
        confirmed += 1;
      }
    }

    const queues = Array.from({ length: 40 }, (_, w) => orderIds.filter((_, i) => i % 40 === w));
    await Promise.all(queues.map(worker));

    assert.equal(confirmed, 250);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 0, reserved: 0, sold: 250 });
  });

  test('addStock running alongside reserves loses neither the restock nor any hold', async () => {
    const { svc } = await stocked({ [DROP]: 50 });

    const reserves = Array.from({ length: 50 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: DROP, qty: 1 }]));
    const restocks = Array.from({ length: 10 }, () => svc.addStock(DROP, 5));
    await Promise.all([...reserves, ...restocks]);

    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 100, reserved: 50, sold: 0 });
  });
});

describe('INC-5521: reserved went negative and did not recover', () => {
  test('expire skips committed orders instead of releasing their units a second time', async () => {
    let now = 0;
    const { svc } = await stocked({ [DROP]: 5 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);
    await svc.commit('o1');

    now = 5000;
    assert.deepEqual(await svc.expire(), []);

    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 3, reserved: 0, sold: 2 });
  });

  test('release rejects a committed order with OrderStateError and changes nothing', async () => {
    const { svc } = await stocked({ [DROP]: 5 });
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);
    await svc.commit('o1');

    await assert.rejects(svc.release('o1'), err => {
      assert.ok(err instanceof OrderStateError);
      assert.equal(err.status, 'committed');
      assert.equal(err.orderId, 'o1');
      return true;
    });
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 3, reserved: 0, sold: 2 });
  });

  test('concurrent releases of one order return its units once', async () => {
    const { svc } = await stocked({ [DROP]: 10 });
    await svc.reserve('keep', [{ sku: DROP, qty: 3 }]);
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);

    const results = await Promise.all(Array.from({ length: 5 }, () => svc.release('o1')));

    for (const result of results) {
      assert.equal(result.status, 'released');
    }
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 3, sold: 0 });
  });

  test('concurrent commit and release of one order apply exactly one of them', async () => {
    for (const first of ['commit', 'release']) {
      const { svc, store } = await stocked({ [DROP]: 10 });
      await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);

      const second = first === 'commit' ? 'release' : 'commit';
      const results = await Promise.allSettled([svc[first]('o1'), svc[second]('o1')]);

      assert.equal(results[0].status, 'fulfilled', `${first} should win`);
      assert.equal(results[1].status, 'rejected', `${second} should lose`);
      assert.ok(results[1].reason instanceof OrderStateError);
      await assertCountersMatchOrders(assert, svc, store, { [DROP]: 10 });
      const snap = await svc.snapshot(DROP);
      assert.equal(snap.reserved, 0);
    }
  });
});

describe('INC-5521: a retried checkout held units twice for one order', () => {
  test('a retry that arrives while the first reserve is still writing holds the units once', async () => {
    const store = new GatedStore();
    const { svc } = await stocked({ [DROP]: 10 }, { store });

    // The first request stalls on its order write, which is where checkout
    // timed out and retried.
    const stall = store.stallNext('set', 'order:o1');
    const first = svc.reserve('o1', [{ sku: DROP, qty: 2 }]);
    await stall.reached;
    const retry = svc.reserve('o1', [{ sku: DROP, qty: 2 }]);
    await ticks(50);
    stall.open();

    const [original, retried] = await Promise.all([first, retry]);
    assert.deepEqual(retried, original);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 10, reserved: 2, sold: 0 });

    await svc.commit('o1');
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 8, reserved: 0, sold: 2 });
  });

  test('many concurrent retries of one order all return the same single reservation', async () => {
    const { svc } = await stocked({ [DROP]: 10, laces: 10 });
    const items = [{ sku: DROP, qty: 2 }, { sku: 'laces', qty: 1 }];

    const results = await Promise.all(Array.from({ length: 20 }, () => svc.reserve('o1', items)));

    for (const result of results) {
      assert.deepEqual(result, { orderId: 'o1', status: 'reserved', items });
    }
    assert.equal(await svc.available(DROP), 8);
    assert.equal(await svc.available('laces'), 9);
  });
});

describe('INC-5521: a rejected bundle left its other item held', () => {
  test('insufficient stock on a later bundle item holds nothing', async () => {
    const { svc, store } = await stocked({ [DROP]: 5, socks: 1 });

    await assert.rejects(
      svc.reserve('bundle', [{ sku: DROP, qty: 1 }, { sku: 'socks', qty: 2 }]),
      err => err instanceof InsufficientStockError && err.sku === 'socks' && err.available === 1
    );

    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 5, reserved: 0, sold: 0 });
    assert.deepEqual(await svc.snapshot('socks'), { sku: 'socks', stock: 1, reserved: 0, sold: 0 });
    assert.equal(await store.get('order:bundle'), undefined);
  });

  test('an unknown sku on a later bundle item holds nothing', async () => {
    const { svc } = await stocked({ [DROP]: 5 });

    await assert.rejects(
      svc.reserve('bundle', [{ sku: DROP, qty: 1 }, { sku: 'discontinued', qty: 1 }]),
      UnknownSkuError
    );

    assert.equal(await svc.available(DROP), 5);
  });

  test('competing bundles for a scarce item leave no orphaned holds on the other item', async () => {
    const { svc, store } = await stocked({ [DROP]: 100, socks: 10 });

    const results = await Promise.allSettled(
      Array.from({ length: 40 }, (_, i) =>
        svc.reserve(`bundle-${i}`, [{ sku: DROP, qty: 1 }, { sku: 'socks', qty: 1 }])
      )
    );

    const { fulfilled, rejected } = outcomes(results);
    assert.equal(fulfilled.length, 10);
    assert.ok(rejected.every(({ reason }) => reason instanceof InsufficientStockError));
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 100, reserved: 10, sold: 0 });
    await assertCountersMatchOrders(assert, svc, store, { [DROP]: 100, socks: 10 });
  });
});

describe('INC-5521: sold counts higher than orders shipped', () => {
  test('a retried commit that overlaps the first sells the units once', async () => {
    const store = new GatedStore();
    const { svc } = await stocked({ [DROP]: 10 }, { store });
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);

    const stall = store.stallNext('set', 'order:o1');
    const first = svc.commit('o1');
    await stall.reached;
    const retry = svc.commit('o1');
    await ticks(50);
    stall.open();

    const [original, retried] = await Promise.all([first, retry]);
    assert.equal(original.status, 'committed');
    assert.deepEqual(retried, original);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 8, reserved: 0, sold: 2 });
  });

  test('expire leaves committed orders committed so shipping still sees them', async () => {
    let now = 0;
    const { svc, store } = await stocked({ [DROP]: 10 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('shipped', [{ sku: DROP, qty: 3 }]);
    await svc.commit('shipped');
    await svc.reserve('abandoned', [{ sku: DROP, qty: 1 }]);

    now = 5000;
    assert.deepEqual(await svc.expire(), ['abandoned']);

    assert.equal((await store.get('order:shipped')).status, 'committed');
    assert.equal((await store.get('order:abandoned')).status, 'released');
    await assertCountersMatchOrders(assert, svc, store, { [DROP]: 10 });
  });

  test('expire racing a commit on a stale reservation applies exactly one of them', async () => {
    let now = 0;
    const { svc, store } = await stocked({ [DROP]: 10 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);
    now = 5000;

    const [commit, expired] = await Promise.allSettled([svc.commit('o1'), svc.expire()]);

    const status = (await store.get('order:o1')).status;
    if (commit.status === 'fulfilled') {
      assert.equal(status, 'committed');
      assert.deepEqual(expired.value, []);
    } else {
      assert.ok(commit.reason instanceof OrderStateError);
      assert.equal(status, 'released');
      assert.deepEqual(expired.value, ['o1']);
    }
    await assertCountersMatchOrders(assert, svc, store, { [DROP]: 10 });
  });

  test('a stalled expire that already listed an order does not release it after commit', async () => {
    let now = 0;
    const store = new GatedStore();
    const { svc } = await stocked({ [DROP]: 10 }, { store, now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: DROP, qty: 2 }]);
    now = 5000;

    // expire has listed the order and stalls reading it; checkout commits
    // the order in the meantime.
    const stall = store.stallNext('get', 'order:o1');
    const expiring = svc.expire();
    await stall.reached;
    const committed = svc.commit('o1');
    await ticks(50);
    stall.open();

    const [reservation, released] = await Promise.all([committed, expiring]);
    assert.equal(reservation.status, 'committed');
    assert.deepEqual(released, []);
    assert.deepEqual(await svc.snapshot(DROP), { sku: DROP, stock: 8, reserved: 0, sold: 2 });
  });
});

