  });

  test('an empty key list runs fn without locking anything', async () => {
    const lock = new KeyedLock();
    assert.equal(await lock.run([], async () => lock.size), 0);
  });

  test('size counts keys in use and drops to zero once every holder finishes', async () => {
    const lock = new KeyedLock();
    let unblock;
    const gate = new Promise(resolve => { unblock = resolve; });

