    await Promise.all(holders);
    assert.equal(lock.size, 0);
  });

  test('ten thousand distinct keys leave nothing behind', async () => {
    const lock = new KeyedLock();
    await Promise.all(Array.from({ length: 10000 }, (_, i) => lock.run([`sku:${i}`], async () => i)));
    assert.equal(lock.size, 0);
  });
