'use strict';

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError
} = require('../src');
const { FlakyStore, SharedReferenceStore, allOrders, assertCountersMatchOrders } = require('./helpers/stores');

async function stocked(stock, options = {}) {
  const store = options.store || new Store();
  const svc = new InventoryService({ ...options, store });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return { svc, store };
}

function deepFreeze(value) {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(deepFreeze);
    Object.freeze(value);
  }
  return value;
}

describe('store failures', () => {
  test('a failed sku write during a bundle reserve restores every sku and records no order', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5, b: 5 }, { store });
    const error = store.failNext('set', 'sku:b');

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }]), err => err === error);

    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 0, sold: 0 });
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 5, reserved: 0, sold: 0 });
    assert.equal(await store.get('order:o1'), undefined);

    await svc.reserve('o1', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }]);
    assert.equal(await svc.available('a'), 4);
    assert.equal(await svc.available('b'), 4);
  });

  test('a failed order write during reserve returns the held units', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, { store });
    const error = store.failNext('set', 'order:o1');

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 2 }]), err => err === error);

    assert.equal(await svc.available('a'), 5);
    assert.equal(await store.get('order:o1'), undefined);
  });

  test('a failed read during reserve holds nothing', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5, b: 5 }, { store });
    const error = store.failNext('get', 'sku:b');

