      await assert.rejects(svc.reserve(orderId, [{ sku: 'a', qty: 1 }]), ValidationError);
      await assert.rejects(svc.commit(orderId), ValidationError);
      await assert.rejects(svc.release(orderId), ValidationError);
      assert.equal(await svc.available('a'), 5);
    });
  }

  const badItems = [
    ['null', null],
    ['a string', 'a'],
    ['an empty array', []],
    ['a null entry', [null]],
    ['a missing qty', [{ sku: 'a' }]],
    ['a zero qty', [{ sku: 'a', qty: 0 }]],
    ['a negative qty', [{ sku: 'a', qty: -1 }]],
    ['a fractional qty', [{ sku: 'a', qty: 1.5 }]],
