    ['an empty sku', [{ sku: '', qty: 1 }]],
    ['a duplicate sku', [{ sku: 'a', qty: 1 }, { sku: 'a', qty: 1 }]]
  ];
  for (const [label, items] of badItems) {
    test(`reserve rejects items with ${label} and holds nothing`, async () => {
      const { svc, store } = await stocked({ a: 5 });
      await assert.rejects(svc.reserve('o1', items), ValidationError);
