    });
  }

  test('addStock, available and snapshot reject invalid skus and quantities', async () => {
    const { svc } = await stocked({ a: 5 });
    for (const sku of ['', ' ', null, 7]) {
      await assert.rejects(svc.addStock(sku, 1), ValidationError);
      await assert.rejects(svc.available(sku), ValidationError);
      await assert.rejects(svc.snapshot(sku), ValidationError);
    }
    for (const qty of [0, -3, 2.5, NaN, Infinity, '4']) {
      await assert.rejects(svc.addStock('a', qty), ValidationError);
    }
    assert.equal(await svc.available('a'), 5);
  });

  test('validation fails before the store is touched', async () => {
    const failing = new Error('store must not be called');
    const store = { get: async () => { throw failing; }, set: async () => { throw failing; }, keys: async () => { throw failing; } };
    const svc = new InventoryService({ store });

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 0 }]), ValidationError);
    await assert.rejects(svc.addStock('', 1), ValidationError);
    await assert.rejects(svc.commit(''), ValidationError);
