    items[0].qty = 4;
    items.push({ sku: 'b', qty: 1 });
    const reservation = await pending;

    assert.deepEqual(reservation.items, [{ sku: 'a', qty: 1 }]);
    assert.equal(await svc.available('a'), 4);
    assert.equal(await svc.available('b'), 5);
