describe('order lifecycle boundaries', () => {
  test('taking the last unit leaves zero available and the next reserve reports zero', async () => {
    const { svc } = await stocked({ a: 1 });
    await svc.reserve('o1', [{ sku: 'a', qty: 1 }]);

    await assert.rejects(svc.reserve('o2', [{ sku: 'a', qty: 1 }]), err =>
      err instanceof InsufficientStockError && err.available === 0 && err.requested === 1
    );
    assert.equal(await svc.available('a'), 0);
  });

  test('an orderId rejected for stock can reserve once stock arrives', async () => {
    const { svc } = await stocked({ a: 1 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 2 }]), InsufficientStockError);

    await svc.addStock('a', 1);
    const reservation = await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);

    assert.equal(reservation.status, 'reserved');
    assert.equal(await svc.available('a'), 0);
  });

  test('reserving a committed or released orderId returns it and holds nothing', async () => {
    const { svc } = await stocked({ a: 5 });
    await svc.reserve('done', [{ sku: 'a', qty: 1 }]);
    await svc.commit('done');
    await svc.reserve('gone', [{ sku: 'a', qty: 1 }]);
    await svc.release('gone');

    assert.equal((await svc.reserve('done', [{ sku: 'a', qty: 3 }])).status, 'committed');
    assert.equal((await svc.reserve('gone', [{ sku: 'a', qty: 3 }])).status, 'released');
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 4, reserved: 0, sold: 1 });
  });

  test('expire keeps a reservation exactly at the ttl and releases one a millisecond older', async () => {
    let now = 0;
    const { svc } = await stocked({ a: 5 }, { now: () => now, reservationTtlMs: 1000 });
    await svc.reserve('older', [{ sku: 'a', qty: 1 }]);
    now = 1;
    await svc.reserve('boundary', [{ sku: 'a', qty: 1 }]);

    now = 1001;
    assert.deepEqual(await svc.expire(), ['older']);
    assert.equal(await svc.available('a'), 4);
  });

  test('expire with nothing to do returns an empty list', async () => {
    const { svc } = await stocked({ a: 5 });
    assert.deepEqual(await svc.expire(), []);
    await svc.reserve('fresh', [{ sku: 'a', qty: 1 }]);
    assert.deepEqual(await svc.expire(), []);
  });
});

