'use strict';

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError
} = require('../src');
const { FlakyStore, SharedReferenceStore, allOrders, assertCountersMatchOrders } = require('./helpers/stores');

async function stocked(stock, options = {}) {
  const store = options.store || new Store();
  const svc = new InventoryService({ ...options, store });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return { svc, store };
}

function deepFreeze(value) {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(deepFreeze);
    Object.freeze(value);
  }
  return value;
}

describe('store failures', () => {
  test('a failed sku write during a bundle reserve restores every sku and records no order', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5, b: 5 }, { store });
    const error = store.failNext('set', 'sku:b');

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }]), err => err === error);

    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 0, sold: 0 });
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 5, reserved: 0, sold: 0 });
    assert.equal(await store.get('order:o1'), undefined);

    await svc.reserve('o1', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }]);
    assert.equal(await svc.available('a'), 4);
    assert.equal(await svc.available('b'), 4);
  });

  test('a failed order write during reserve returns the held units', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, { store });
    const error = store.failNext('set', 'order:o1');

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 2 }]), err => err === error);

    assert.equal(await svc.available('a'), 5);
    assert.equal(await store.get('order:o1'), undefined);
  });

  test('a failed read during reserve holds nothing', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5, b: 5 }, { store });
    const error = store.failNext('get', 'sku:b');

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }]), err => err === error);

    assert.equal(await svc.available('a'), 5);
  });

  test('a failed order write during commit leaves the order reserved so the retry sells once', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, { store });
    await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    const error = store.failNext('set', 'order:o1');

    await assert.rejects(svc.commit('o1'), err => err === error);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 2, sold: 0 });
    assert.equal((await store.get('order:o1')).status, 'reserved');

    await svc.commit('o1');
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 3, reserved: 0, sold: 2 });
  });

  test('a failed sku write during release leaves the order reserved and its units held', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5, b: 5 }, { store });
    await svc.reserve('o1', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }]);
    store.failNext('set', 'sku:b');

    await assert.rejects(svc.release('o1'), /store unavailable: set sku:b/);
    await assertCountersMatchOrders(assert, svc, store, { a: 5, b: 5 });
    assert.equal(await svc.available('a'), 3);

    await svc.release('o1');
    assert.equal(await svc.available('a'), 5);
  });

  test('when restoring also fails the error carries both failures and names the skus', async () => {
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, { store });
    const writeError = store.failNext('set', 'order:o1');
    const restoreError = store.failNext('set', 'sku:a', { skip: 1 });

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 2 }]), err => {
      assert.ok(err instanceof AggregateError);
      assert.deepEqual(err.errors, [writeError, restoreError]);
      assert.match(err.message, /sku:a/);
      return true;
    });
  });

  test('a failed listing makes expire reject without releasing anything', async () => {
    let now = 0;
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, { store, now: () => now, reservationTtlMs: 10 });
    await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    now = 100;
    const error = store.failNext('keys', 'order:');

    await assert.rejects(svc.expire(), err => err === error);
    assert.equal(await svc.available('a'), 3);
  });

  test('a failed write during expire leaves that order for the next pass', async () => {
    let now = 0;
    const store = new FlakyStore();
    const { svc } = await stocked({ a: 5 }, { store, now: () => now, reservationTtlMs: 10 });
    await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    now = 100;
    store.failNext('set', 'order:o1');

    await assert.rejects(svc.expire(), /store unavailable/);
    assert.equal(await svc.available('a'), 3);
    assert.equal((await store.get('order:o1')).status, 'reserved');

    assert.deepEqual(await svc.expire(), ['o1']);
    assert.equal(await svc.available('a'), 5);
  });
});

describe('stores other than src/store.js', () => {
  test('a store that returns live references keeps counters correct through a full lifecycle', async () => {
    let now = 0;
    const store = new SharedReferenceStore();
    const { svc } = await stocked({ a: 10, b: 10 }, { store, now: () => now, reservationTtlMs: 10 });

    await svc.reserve('sold', [{ sku: 'a', qty: 2 }, { sku: 'b', qty: 1 }]);
    await svc.commit('sold');
    await svc.reserve('cancelled', [{ sku: 'a', qty: 1 }]);
    await svc.release('cancelled');
    await svc.reserve('stale', [{ sku: 'b', qty: 4 }]);
    await assert.rejects(svc.reserve('short', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 99 }]), InsufficientStockError);
    now = 100;

    assert.deepEqual(await svc.expire(), ['stale']);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 8, reserved: 0, sold: 2 });
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 9, reserved: 0, sold: 1 });
  });

  test('a store that returns live references rolls back to the values it read', async () => {
    const store = new FlakyStore(new SharedReferenceStore());
    const { svc } = await stocked({ a: 5 }, { store });
    store.failNext('set', 'order:o1');

    await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 2 }]), /store unavailable/);

    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 5, reserved: 0, sold: 0 });
  });

  test('a store that returns live references does not oversell under concurrent reserves', async () => {
    const store = new SharedReferenceStore();
    const { svc } = await stocked({ drop: 20 }, { store });

    const results = await Promise.allSettled(
      Array.from({ length: 40 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'drop', qty: 1 }]))
    );

    assert.equal(results.filter(result => result.status === 'fulfilled').length, 20);
    assert.deepEqual(await svc.snapshot('drop'), { sku: 'drop', stock: 20, reserved: 20, sold: 0 });
  });

  test('a store whose methods return plain values instead of promises', async () => {
    const data = new Map();
    const store = {
      get: key => structuredClone(data.get(key)),
      set: (key, value) => { data.set(key, structuredClone(value)); },
      keys: prefix => [...data.keys()].filter(key => key.startsWith(prefix))
    };
    const { svc } = await stocked({ a: 3 }, { store });

    await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
    await svc.commit('o1');
    await assert.rejects(svc.reserve('o2', [{ sku: 'a', qty: 2 }]), InsufficientStockError);

    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 1, reserved: 0, sold: 2 });
  });
});

