'use strict';

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  OrderStateError,
  UnknownOrderError
} = require('../src');
const {
  ticks,
  createRng,
  GatedStore,
  JitterStore,
  CountingStore,
  allOrders,
  assertCountersMatchOrders
} = require('./helpers/stores');

const BLOCKED = Symbol('blocked');

// Resolves to BLOCKED if `promise` has not settled after `n` event-loop turns.
// A call that needs no lock finishes in a handful of turns.
function withinTicks(promise, n = 200) {
  return Promise.race([promise, ticks(n).then(() => BLOCKED)]);
}

async function stocked(stock, store = new Store()) {
  const svc = new InventoryService({ store });
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

describe('calls that share no sku and no order do not wait for each other', () => {
  test('checkout on one sku completes while a call on another sku is stalled mid-write', async () => {
    const store = new GatedStore();
    const svc = await stocked({ a: 10, b: 10 }, store);
    const stall = store.stallNext('set', 'sku:a');
    const stalled = svc.reserve('o-a', [{ sku: 'a', qty: 1 }]);
    await stall.reached;

    const reserved = await withinTicks(svc.reserve('o-b', [{ sku: 'b', qty: 2 }]));
    assert.notEqual(reserved, BLOCKED, 'reserve on b waited for the stalled call on a');
    assert.notEqual(await withinTicks(svc.commit('o-b')), BLOCKED);
    assert.notEqual(await withinTicks(svc.addStock('b', 1)), BLOCKED);
    assert.notEqual(await withinTicks(svc.reserve('o-b2', [{ sku: 'b', qty: 1 }])), BLOCKED);
    assert.notEqual(await withinTicks(svc.release('o-b2')), BLOCKED);
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 9, reserved: 0, sold: 2 });

    stall.open();
    await stalled;
    assert.equal(await svc.available('a'), 9);
  });

  test('reads of a sku are not blocked by a stalled write to it', async () => {
    const store = new GatedStore();
    const svc = await stocked({ a: 10 }, store);
    const stall = store.stallNext('set', 'order:o1');
    const stalled = svc.reserve('o1', [{ sku: 'a', qty: 1 }]);
    await stall.reached;

    assert.equal(await withinTicks(svc.available('a')), 9);
    assert.notEqual(await withinTicks(svc.snapshot('a')), BLOCKED);

    stall.open();
    await stalled;
  });

  test('an expire pass stalled on one order does not block checkout elsewhere', async () => {
    let now = 0;
    const store = new GatedStore();
    const svc = new InventoryService({ store, now: () => now, reservationTtlMs: 1000 });
    await svc.addStock('a', 10);
    await svc.addStock('b', 10);
    await svc.reserve('stale', [{ sku: 'a', qty: 1 }]);
    now = 5000;

    const stall = store.stallNext('set', 'order:stale');
    const expiring = svc.expire();
    await stall.reached;

    assert.notEqual(await withinTicks(svc.reserve('fresh', [{ sku: 'b', qty: 1 }])), BLOCKED);
    assert.notEqual(await withinTicks(svc.commit('fresh')), BLOCKED);

    stall.open();
    assert.deepEqual(await expiring, ['stale']);
  });

  test('calls on the same sku do wait for each other', async () => {
    const store = new GatedStore();
    const svc = await stocked({ a: 10 }, store);
    const stall = store.stallNext('set', 'sku:a');
    const first = svc.reserve('o1', [{ sku: 'a', qty: 1 }]);
    await stall.reached;

    const second = svc.reserve('o2', [{ sku: 'a', qty: 1 }]);
    assert.equal(await withinTicks(second), BLOCKED);

    stall.open();
    await Promise.all([first, second]);
    assert.equal(await svc.available('a'), 8);
  });

  test('reserves on distinct skus overlap their store calls', async () => {
    const store = new CountingStore();
    const skus = Array.from({ length: 50 }, (_, i) => `sku-${i}`);
    const svc = new InventoryService({ store });
    await Promise.all(skus.map(sku => svc.addStock(sku, 1)));
    store.maxInFlight = 0;

    await Promise.all(skus.map((sku, i) => svc.reserve(`o${i}`, [{ sku, qty: 1 }])));

    // Under a service-wide lock only one call is ever in flight.
    assert.ok(store.maxInFlight >= skus.length, `max in flight was ${store.maxInFlight}`);
  });

  test('a bundle reads and writes its skus in parallel', async () => {
    const store = new CountingStore();
    const svc = await stocked({ a: 1, b: 1, c: 1 }, store);
    store.maxInFlight = 0;

    await svc.reserve('bundle', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }, { sku: 'c', qty: 1 }]);

    assert.equal(store.maxInFlight, 3);
  });
});

describe('services sharing one store', () => {
  test('two service instances over one store do not oversell between them', async () => {
    const store = new Store();
    const workers = [new InventoryService({ store }), new InventoryService({ store })];
    await workers[0].addStock('drop', 100);

    const results = await Promise.allSettled(
      Array.from({ length: 150 }, (_, i) => workers[i % 2].reserve(`order-${i}`, [{ sku: 'drop', qty: 1 }]))
    );

    assert.equal(results.filter(result => result.status === 'fulfilled').length, 100);
    assert.deepEqual(await workers[1].snapshot('drop'), { sku: 'drop', stock: 100, reserved: 100, sold: 0 });
  });

  test('a retry routed to a different worker still returns the first reservation', async () => {
    const store = new GatedStore();
    const first = new InventoryService({ store });
    const second = new InventoryService({ store });
    await first.addStock('drop', 10);

    const stall = store.stallNext('set', 'order:o1');
    const original = first.reserve('o1', [{ sku: 'drop', qty: 3 }]);
    await stall.reached;
    const retry = second.reserve('o1', [{ sku: 'drop', qty: 3 }]);
    await ticks(50);
    stall.open();

    assert.deepEqual(await retry, await original);
    assert.equal(await first.available('drop'), 7);
  });

  test('services over different stores keep separate stock', async () => {
    const east = await stocked({ drop: 1 });
    const west = await stocked({ drop: 1 });

    await Promise.all([east.reserve('o1', [{ sku: 'drop', qty: 1 }]), west.reserve('o1', [{ sku: 'drop', qty: 1 }])]);

    assert.equal(await east.available('drop'), 0);
    assert.equal(await west.available('drop'), 0);
  });
});

const EXPECTED_ERRORS = [InsufficientStockError, OrderStateError, UnknownOrderError];

// A seeded mix of checkout traffic: overlapping bundles, retries of the same
// order, commits and releases racing each other, restocks and expire passes.
async function runWorkload({ seed, store, workerCount }) {
  const rng = createRng(seed);
  const pick = list => list[Math.floor(rng() * list.length)];
  let clock = 0;
  const workers = Array.from({ length: workerCount }, () =>
    new InventoryService({ store, now: () => ++clock, reservationTtlMs: 400 })
  );
  const skus = ['a', 'b', 'c', 'd', 'e'];
  const stockAdded = {};
  for (const sku of skus) {
    await workers[0].addStock(sku, 15);
    stockAdded[sku] = 15;
  }
  const orderIds = Array.from({ length: 120 }, (_, i) => `order-${i}`);

  const plan = Array.from({ length: 600 }, () => {
    const roll = rng();
    const worker = pick(workers);
    const delay = Math.floor(rng() * 60);
    if (roll < 0.4) {
      const count = 1 + Math.floor(rng() * 3);
      const chosen = [...skus].sort(() => rng() - 0.5).slice(0, count);
      const items = chosen.map(sku => ({ sku, qty: 1 + Math.floor(rng() * 3) }));
      const orderId = pick(orderIds);
      return { delay, run: () => worker.reserve(orderId, items) };
    }
    if (roll < 0.65) {
      const orderId = pick(orderIds);
      return { delay, run: () => worker.commit(orderId) };
    }
    if (roll < 0.9) {
      const orderId = pick(orderIds);
      return { delay, run: () => worker.release(orderId) };
    }
    if (roll < 0.97) {
      const sku = pick(skus);
      const qty = 1 + Math.floor(rng() * 4);
      return {
        delay,
        run: async () => {
          await worker.addStock(sku, qty);
          stockAdded[sku] += qty;
        }
      };
    }
    return { delay, run: () => worker.expire() };
  });

  const violations = [];
  let running = true;
  const sampler = (async () => {
    while (running) {
      const snapshots = await Promise.all(skus.map(sku => workers[0].snapshot(sku)));
      for (const snap of snapshots) {
        if (snap.reserved < 0 || snap.stock - snap.reserved < 0 || snap.sold < 0) {
          violations.push(snap);
        }
      }
    }
  })();

  const unexpected = [];
  await Promise.all(plan.map(async ({ delay, run }) => {
    await ticks(delay);
    try {
      await run();
    } catch (err) {
      if (!EXPECTED_ERRORS.some(type => err instanceof type)) {
        unexpected.push(err);
      }
    }
  }));
  running = false;
  await sampler;

  return { svc: workers[0], stockAdded, violations, unexpected };
}

describe('randomised concurrent checkout workload', () => {
  const cases = [
    { name: 'one service, default store', seed: 5521, workerCount: 1, store: () => new Store() },
    { name: 'four services sharing a store', seed: 5490, workerCount: 4, store: () => new Store() },
    { name: 'one service, store with random latency', seed: 912, workerCount: 1, store: () => new JitterStore(912) }
  ];

  for (const { name, seed, workerCount, store: makeStore } of cases) {
    test(`${name}: counters always match the order records`, { timeout: 20000 }, async () => {
      const store = makeStore();
      const { svc, stockAdded, violations, unexpected } = await runWorkload({ seed, store, workerCount });

      assert.deepEqual(unexpected, []);
      assert.deepEqual(violations, [], 'a snapshot showed negative reserved, available or sold');
      await assertCountersMatchOrders(assert, svc, store, stockAdded);
      const statuses = new Set((await allOrders(store)).map(order => order.status));
      for (const status of ['reserved', 'committed', 'released']) {
        assert.ok(statuses.has(status), `workload never produced a ${status} order`);
      }
    });
  }
});

