+/**
+ * Per-key mutual exclusion for async critical sections.
+ *
+ * Each key has its own FIFO queue, so callers that lock disjoint keys never
+ * wait for each other. A key's entry is removed when its last holder
+ * releases, so the table only grows with the number of keys in use right now.
+ */
+class KeyedLock {
+  constructor() {
+    // key -> promise that resolves when the most recent holder or waiter
+    // for that key releases.
+    this.tails = new Map();
+  }
+
+  /** Number of keys currently held or waited on. */
+  get size() {
+    return this.tails.size;
+  }
+
+  /**
+   * Run `fn` while holding every key in `keys`, and return its result.
+   *
+   * Keys are acquired one at a time in sorted order, so two callers locking
+   * overlapping sets cannot deadlock. The locks are not re-entrant: calling
+   * `run` for a key the caller already holds waits forever.
+   */
+  async run(keys, fn) {
+    const ordered = [...new Set(keys)].sort();
+    const releases = [];
+    try {
+      for (const key of ordered) {
+        // Sequential on purpose: taking the keys in a fixed order is what
+        // rules out deadlock.
+        releases.push(await this.acquire(key));
+      }
+      return await fn();
+    } finally {
+      for (const release of releases.reverse()) {
+        release();
+      }
+    }
+  }
+
+  /** Wait for `key` and resolve to the function that releases it. */
+  acquire(key) {
+    const previous = this.tails.get(key);
+    let release;
+    const released = new Promise(resolve => { release = resolve; });
+    this.tails.set(key, released);
+    const unlock = () => {
+      release();
+      if (this.tails.get(key) === released) {
+        this.tails.delete(key);
+      }
+    };
+    return previous ? previous.then(() => unlock) : Promise.resolve(unlock);
+  }
+}
