'use strict';

// Test stores with the same get/set/keys surface as src/store.js. Each one
// changes a single property of the store so a test can pin down one
// interleaving or failure.

const { Store } = require('../../src/store');

/** Yield to the event loop `n` times so pending store calls can make progress. */
async function ticks(n) {
  for (let i = 0; i < n; i++) {
    await new Promise(resolve => setImmediate(resolve));
  }
}

/** Deterministic PRNG (mulberry32) returning floats in [0, 1). */
function createRng(seed) {
  let state = seed >>> 0;
  return function next() {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Stalls one chosen call until the test opens it. Used to hold a request
 * mid-flight, the way a slow store write did before checkout timed out and
 * retried.
 */
class GatedStore {
  constructor(inner = new Store()) {
    this.inner = inner;
    this.gates = [];
  }

  /**
   * Stall the next `op` ('get' | 'set' | 'keys') on `key`. `reached` resolves
   * when that call arrives; the call proceeds after `open()`.
   */
  stallNext(op, key) {
    let arrive;
    let open;
    const reached = new Promise(resolve => { arrive = resolve; });
    const opened = new Promise(resolve => { open = resolve; });
    this.gates.push({ op, key, arrive, opened });
    return { reached, open };
  }

  async pass(op, key) {
    const index = this.gates.findIndex(gate => gate.op === op && gate.key === key);
    if (index === -1) {
      return;
    }
    const [gate] = this.gates.splice(index, 1);
    gate.arrive();
    await gate.opened;
  }

  async get(key) {
    await this.pass('get', key);
    return this.inner.get(key);
  }

  async set(key, value) {
    await this.pass('set', key);
    return this.inner.set(key, value);
  }

  async keys(prefix) {
    await this.pass('keys', prefix);
    return this.inner.keys(prefix);
  }
}

/** Rejects chosen calls, to exercise the service's handling of store errors. */
class FlakyStore {
  constructor(inner = new Store()) {
    this.inner = inner;
    this.failures = [];
  }

  /**
   * Make one upcoming `op` call on `key` reject, after letting `skip`
   * matching calls through. Returns the error it will reject with.
   */
  failNext(op, key, { skip = 0, error = new Error(`store unavailable: ${op} ${key}`) } = {}) {
    this.failures.push({ op, key, skip, error });
    return error;
  }

  async maybeFail(op, key) {
    await ticks(1);
    const index = this.failures.findIndex(failure => failure.op === op && failure.key === key);
    if (index === -1) {
      return;
    }
    const failure = this.failures[index];
    if (failure.skip > 0) {
      failure.skip -= 1;
      return;
    }
    this.failures.splice(index, 1);
    throw failure.error;
  }

  async get(key) {
    await this.maybeFail('get', key);
    return this.inner.get(key);
  }

  async set(key, value) {
    await this.maybeFail('set', key);
    return this.inner.set(key, value);
  }

  async keys(prefix) {
    await this.maybeFail('keys', prefix);
    return this.inner.keys(prefix);
  }
}

/**
 * Hands out the stored objects themselves instead of copies, like a naive
 * in-process cache. Any in-place mutation by the service shows up as a
 * change to stored state before a write.
 */
class SharedReferenceStore {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    await ticks(1);
    return this.data.get(key);
  }

  async set(key, value) {
    await ticks(1);
    this.data.set(key, value);
  }

  async keys(prefix) {
    await ticks(1);
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

