'use strict';
// Fully synchronous store (returns plain values, throws synchronously).
// Order write fails, then restore of sku:b throws synchronously: sku:c is never
// restored and the caller gets a bare Error instead of the documented AggregateError.
const { InventoryService } = require('../src');
class SyncStore {
  constructor() { this.data = new Map(); this.failOrder = false; this.failBRestore = false; this.bWrites = 0; }
  get(k) { const v = this.data.get(k); return v === undefined ? undefined : structuredClone(v); }
  keys(p) { return [...this.data.keys()].filter(k => k.startsWith(p)); }
  set(k, v) {
    if (k.startsWith('order:') && this.failOrder) throw new Error('order write failed');
    if (k === 'sku:b' && this.failBRestore && ++this.bWrites === 2) throw new Error('restore of b failed');
    this.data.set(k, structuredClone(v));
  }
}
(async () => {
  const s = new SyncStore(); const inv = new InventoryService({ store: s });
  for (const k of ['a', 'b', 'c']) await inv.addStock(k, 5);
