'use strict';
// Randomized interleavings: 3 services over one store with random per-call latency
// (reorders calls), random async rejections (not applied), live-reference or cloning,
// concurrent expire. Checks counters against order records and that nothing hangs.
const { InventoryService } = require('../src');
function rng(seed) { let s = seed >>> 0; return () => { s = (s + 0x6d2b79f5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
class ChaosStore {
  constructor(r, { clone, failRate }) { this.d = new Map(); this.r = r; this.clone = clone; this.failRate = failRate; this.on = false; }
  delay() { const x = this.r(); return x < 0.3 ? Promise.resolve() : x < 0.6 ? new Promise(res => setImmediate(res)) : new Promise(res => setTimeout(res, Math.floor(this.r() * 3))); }
  c(v) { return this.clone && v !== undefined ? structuredClone(v) : v; }
  async get(k) { await this.delay(); if (this.on && this.r() < this.failRate) throw new Error('get fail'); return this.c(this.d.get(k)); }
  async set(k, v) { await this.delay(); if (this.on && this.r() < this.failRate) throw new Error('set fail'); this.d.set(k, this.c(v)); }
  async keys(p) { await this.delay(); return [...this.d.keys()].filter(k => k.startsWith(p)); }
}
async function run(seed) {
  const r = rng(seed);
  const store = new ChaosStore(r, { clone: r() < 0.5, failRate: r() < 0.5 ? 0 : 0.05 });
  let clock = 1000;
  const svcs = [0, 1, 2].map(() => new InventoryService({ store, reservationTtlMs: 5, now: () => clock }));
  const skus = ['a', 'b', 'c', 'd'];
  const added = {};
  for (const s of skus) { const q = 1 + Math.floor(r() * 4); await svcs[0].addStock(s, q); added[s] = q; }
  store.on = true;
  const ops = [];
  const pick = () => svcs[Math.floor(r() * 3)];
  const orderIds = Array.from({ length: 12 }, (_, i) => 'o' + i);
  let stockAdds = [];
  for (let i = 0; i < 80; i++) {
    const x = r(); const id = orderIds[Math.floor(r() * orderIds.length)];
    if (x < 0.4) {
      const n = 1 + Math.floor(r() * 3); const chosen = [...skus].sort(() => r() - 0.5).slice(0, n);
      ops.push(pick().reserve(id, chosen.map(sku => ({ sku, qty: 1 + Math.floor(r() * 2) }))));
    } else if (x < 0.6) ops.push(pick().commit(id));
    else if (x < 0.8) ops.push(pick().release(id));
    else if (x < 0.9) { clock += 3; ops.push(pick().expire()); }
    else { const s = skus[Math.floor(r() * 4)]; const p = pick().addStock(s, 1); stockAdds.push(p.then(() => added[s]++, () => {})); ops.push(p); }
    if (r() < 0.3) await new Promise(res => setImmediate(res));
  }
  const timeout = new Promise((_, rej) => setTimeout(() => rej(new Error('HANG/DEADLOCK seed ' + seed)), 5000));
  const results = await Promise.race([Promise.allSettled(ops), timeout]);
  await Promise.all(stockAdds);
  const bad = results.filter(x => x.status === 'rejected' && !/fail|Unknown|insufficient|cannot|unknown/.test(x.reason.message));
  if (bad.length) throw new Error('unexpected errors: ' + bad.map(b => b.reason.stack).join('\n'));
  store.on = false;
  const exp = {}; for (const s of skus) exp[s] = { reserved: 0, sold: 0 };
  for (const [k, o] of store.d) if (k.startsWith('order:')) for (const { sku, qty } of o.items) { if (o.status === 'reserved') exp[sku].reserved += qty; if (o.status === 'committed') exp[sku].sold += qty; }
  for (const s of skus) {
    const v = store.d.get('sku:' + s);
    if (v.reserved !== exp[s].reserved || v.sold !== exp[s].sold || v.stock - v.reserved < 0 || v.stock !== added[s] - v.sold || v.reserved < 0)
      throw new Error(`seed ${seed} sku ${s}: ${JSON.stringify(v)} expected ${JSON.stringify(exp[s])} added ${added[s]}`);
  }
}
(async () => {
  const N = Number(process.argv[2] || 400);
  let fails = 0;
  for (let seed = 1; seed <= N; seed++) { try { await run(seed); } catch (e) { fails++; if (fails < 5) console.log(e.message); } }
  console.log(`${N} seeds, ${fails} failures`);
})();
EOF
